// nullptr si inconnu : l'appelant dessine un cadre gris (comme les autres ligues).
static const uint16_t* nbaLogoByAbbrev(const char* abbr){
  for(int i=0;i<(int)NBA_LOGO_COUNT;i++) if(strcmp(NBA_LOGOS[i].abbr, abbr)==0) return NBA_LOGOS[i].data;
  return nullptr;
}

